% Read the file (assuming it's space or comma separated)
data = readmatrix('20250812035751-96075-data.txt');

% Altitude is the 3rd column in KML-like GPS coordinates [lon, lat, alt]
altitude = data(:,4);

alt = altitude;



%% Genearte Cartesian coordinates
lat = table_raw_GPS_coordinates(:, 2);
lon = table_raw_GPS_coordinates(:, 1);
[xEast_CL_GE_raw, yNorth_CL_GE_raw, zUp_CL_GE_raw] = latlon2local(lat, lon, alt, origin);



%% Plot the Cartesian coordinates
figure()
plot3(xEast_CL_GE_raw, yNorth_CL_GE_raw, zUp_CL_GE_raw - min(zUp_CL_GE_raw), '-o')
hold on
plot3(xEast_CL_GE_raw, yNorth_CL_GE_raw, zUp_CL_GE_raw*0, '-o')
axis equal
xlabel('x, m')
ylabel('y, m')
zlabel('z, m')
legend('From LeftBoundary_GE_raw.kml and https://www.gpsvisualizer.com/elevation', 'Projection to the x-y plane')
grid on

%% Save
save('CL_Cartesian_coords_GE_raw', 'xEast_CL_GE_raw', 'yNorth_CL_GE_raw', 'zUp_CL_GE_raw')




